function normalize(value:string){return value.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,' ').trim()}
function scoreText(query:string,text:string){const q=normalize(query);const hay=normalize(text);if(!q)return 0;let score=hay.includes(q)?80:0;for(const token of q.split(/\s+/).filter(Boolean)){if(hay.includes(token))score+=12;else if(hay.split(/\s+/).some(part=>part.startsWith(token)||token.startsWith(part)))score+=5}return score}
function bestSnippet(query:string,text:string){const q=normalize(query).split(/\s+/).find(Boolean);if(!q)return text.slice(0,140);const flat=text.replace(/\s+/g,' ');const index=normalize(flat).indexOf(q);const start=Math.max(0,index-45);return flat.slice(start,start+150)}
function download(book:Runbook){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(book,null,2)],{type:'application/json'}));a.download=`${book.id}.json`;a.click();URL.revokeObjectURL(a.href)}
function folderOf(book:Runbook){return book.folder??book.category??uncategorized}
function folderLabel(name:string,t:Record<string,string>){return name||t.noFolder}
function uniqueFolderId(name:string){return `folder-${Date.now()}-${slugify(name||'sin-carpeta')}`}
function nodeTypeLabel(type:NodeType,t:Record<string,string>){const labels:Record<NodeType,string>={action:'Accion',question:'Pregunta',check:'Comprobacion',command:t.addCommand,troubleshooting:t.addObservedError,warning:t.warning,solution:t.markAsSolution,note:'Nota','visual-identification':'Identificacion visual',multimedia:'Multimedia'};return labels[type]??type}

export default function App(){
 const [books,setBooks]=useState<Runbook[]>(()=>loadLibrary(defaultBooks));
 const [folders,setFolders]=useState<FolderItem[]>(()=>loadFolders(loadLibrary(defaultBooks)));
 const [selected,setSelected]=useState<string>();
 const [targetNode,setTargetNode]=useState<string>();
 const [mode,setMode]=useState<Mode>('library');
 const [site,setSite]=useState(false);
 const [search,setSearch]=useState('');
 const [tagFilter,setTagFilter]=useState('');
 const [folderFilter,setFolderFilter]=useState<string>();
 const [expanded,setExpanded]=useState<Set<string>>(()=>new Set());
 const [newFolder,setNewFolder]=useState('');
 const [deleteFolder,setDeleteFolder]=useState<DeleteFolderIntent>();
 const [moving,setMoving]=useState<MoveMenu>();
 const [importing,setImporting]=useState(false);
 const [creating,setCreating]=useState(false);
 const [quickCreate,setQuickCreate]=useState<string>();
 const [lang,setLang]=useState<Language>(()=>getStoredLanguage());
 const [dark,setDark]=useState(()=>getStoredTheme()?getStoredTheme()==='dark':typeof matchMedia==='function'&&matchMedia('(prefers-color-scheme: dark)').matches);
 const [recents,setRecents]=useState<RecentItem[]>(()=>loadRecents());
 const t=ui[lang];

 useEffect(()=>saveLibrary(books),[books]);
 useEffect(()=>saveFolders(folders),[folders]);
 useEffect(()=>{saveLanguage(lang);document.documentElement.lang=lang},[lang]);
 useEffect(()=>saveTheme(dark),[dark]);
 useEffect(()=>saveRecents(recents),[recents]);

 const book=books.find(item=>item.id===selected);
 const addRecent=useCallback((item:Omit<RecentItem,'id'|'at'>)=>setRecents(items=>[{...item,id:`recent-${Date.now()}`,at:new Date().toISOString()},...items.filter(old=>old.bookId!==item.bookId||old.nodeId!==item.nodeId||old.query!==item.query)].slice(0,24)),[]);
 const update=(next:Runbook)=>setBooks(items=>items.map(item=>item.id===book?.id?next:item));
 const open=(nextBook:Runbook,nextMode:Mode,nodeId?:string)=>{setSelected(nextBook.id);setTargetNode(nodeId);setMode(nextMode);addRecent({bookId:nextBook.id,nodeId,type:nextMode==='run'?'procedure':'step',label:localize(nextBook.title,lang)})};
 const duplicate=(source:Runbook)=>{let id=`${source.id}-copy`,i=2;while(books.some(item=>item.id===id))id=`${source.id}-copy-${i++}`;const copy={...clone(source),id,title:{es:`${localize(source.title,'es')} (copia)`,en:`${localize(source.title,'en')} (Copy)`},metadata:{...source.metadata,updatedAt:new Date().toISOString()}};setBooks(items=>[...items,copy]);open(copy,'edit')};
 const removeBook=(source:Runbook)=>{if(confirm(`${t.deleteGuide}: "${localize(source.title,lang)}"?`))setBooks(items=>items.filter(item=>item.id!==source.id))};
 const runSearch=useMemo(()=>searchResults(books,search,tagFilter,lang),[books,search,tagFilter,lang]);
 const visibleBooks=useMemo(()=>books.filter(item=>(folderFilter===undefined||folderOf(item)===folderFilter)&&(!tagFilter||item.tags.some(tag=>normalize(tag)===normalize(tagFilter)))),[books,folderFilter,tagFilter]);
 const allTags=useMemo(()=>Array.from(new Set(books.flatMap(item=>item.tags))).sort((a,b)=>a.localeCompare(b)),[books]);
 const folderStats=useMemo(()=>folders.map(folder=>({name:folder.name,count:books.filter(book=>folderOf(book)===folder.name).length})).concat(books.some(book=>folderOf(book)===uncategorized)?[{name:uncategorized,count:books.filter(book=>folderOf(book)===uncategorized).length}]:[]),[books,folders]);
 const noRelevant=search.trim()&&runSearch.length===0;
 const ensureFolder=(name:string)=>{if(name)setFolders(items=>items.some(item=>item.name===name)?items:[...items,{id:uniqueFolderId(name),name,createdAt:new Date().toISOString()}])};
 const acceptBook=(next:Runbook)=>{const migrated=migrateRunbook(next);ensureFolder(folderOf(migrated));setBooks(items=>[...items.filter(item=>item.id!==migrated.id),migrated]);setImporting(false);open(migrated,'edit')};
 const createBook=(next:Runbook)=>{ensureFolder(folderOf(next));setBooks(items=>[next,...items]);setCreating(false);open(next,'edit')};
 const saveQuick=(next:Runbook)=>{ensureFolder(folderOf(next));setBooks(items=>[next,...items]);setQuickCreate(undefined);setSearch('');open(next,'edit')};
 const createFolder=()=>{const name=newFolder.trim();if(!name||folders.some(folder=>normalize(folder.name)===normalize(name)))return;setFolders(items=>[...items,{id:uniqueFolderId(name),name,createdAt:new Date().toISOString()}]);setNewFolder('');setFolderFilter(name)};
 const renameFolder=(name:string)=>{const next=prompt(t.rename,name)?.trim();if(!next||next===name)return;setFolders(items=>items.map(folder=>folder.name===name?{...folder,name:next}:folder));setBooks(items=>items.map(book=>folderOf(book)===name?{...book,folder:next,category:next}:book));if(folderFilter===name)setFolderFilter(next)};
 const moveBook=(bookId:string,folder:string)=>{setBooks(items=>items.map(item=>item.id===bookId?{...item,folder,category:folder||item.category}:item));setMoving(undefined)};

 return <div className={dark?'app dark':'app'}>
  <header>
   <button className="brand" onClick={()=>setMode('library')}><span>TR</span><b>Tech Runbook</b></button>
   <div className="header-actions">
    <label className="language-select" title={t.language}><span>{t.language}</span><select value={lang} onChange={event=>setLang(event.target.value as Language)}><option value="es">{t.spanish}</option><option value="en">{t.english}</option></select></label>
    <button className="icon-button" onClick={()=>setDark(value=>!value)} aria-label={t.toggleTheme}>{dark?'Light':'Dark'}</button>
    {mode!=='library'&&<button onClick={()=>setMode('library')}>{t.library}</button>}
   </div>
  </header>

  {mode==='library'&&<main className="home">
   <section className="hero compact-hero">
    <p className="eyebrow">{t.fieldKnowledge}</p>
    <h1>{t.problem}</h1>
    <div className="search-panel" id="search">
     <label className="search"><span>/</span><input aria-label={t.search} placeholder={t.searchPlaceholder} value={search} onChange={event=>{setSearch(event.target.value);if(event.target.value.trim())addRecent({bookId:'search',query:event.target.value,type:'search',label:event.target.value})}}/></label>
     {tagFilter&&<button className="tag-filter" onClick={()=>setTagFilter('')}>{t.filters}: {tagFilter} x</button>}
    </div>
   </section>

   {search.trim()&&<section className="results">
    <div className="toolbar compact"><h2>{t.search}</h2><button onClick={()=>setSearch('')}>{t.clear}</button></div>
    {runSearch.map(result=><article className="result" key={`${result.book.id}-${result.node?.id??'book'}`}>
     <div><div className="category">{result.node?.tags?.join(' / ')||result.book.tags.slice(0,3).join(' / ')}</div><h3>{localize(result.node?.title??result.book.title,lang)}</h3><p>{result.snippet||localize(result.book.description,lang)}</p></div>
     <button className="primary" onClick={()=>{open(result.book,'run',result.node?.id);addRecent({bookId:result.book.id,nodeId:result.node?.id,query:search,type:'resolved',label:localize(result.node?.title??result.book.title,lang)})}}>{t.resolver}</button>
    </article>)}
    {noRelevant&&<div className="empty-state"><h3>{t.noResults}</h3><div><button className="primary" onClick={()=>setQuickCreate(search)}>{t.addSolution}</button><button onClick={()=>setQuickCreate(search)}>{t.createTroubleshooting}</button><button onClick={()=>setSearch('')}>{t.cancel}</button></div></div>}
   </section>}

   <section className="dashboard-grid" id="library">
    <aside className="folder-rail">
     <div className="rail-head"><b>{t.folders}</b><button onClick={()=>setFolderFilter(undefined)} className={folderFilter===undefined?'active':''}>{t.allFolders}</button></div>
     <div className="folder-create"><input value={newFolder} onChange={event=>setNewFolder(event.target.value)} placeholder={t.folder}/><button onClick={createFolder}>{t.newFolder}</button></div>
     <div className="folder-list">
      {folderStats.map(folder=><div className={folderFilter===folder.name?'folder-row active':'folder-row'} key={folder.name||'none'}>
       <button onClick={()=>setFolderFilter(folder.name)}><span>{folderLabel(folder.name,t)}</span><small>{folder.count} {t.procedures.toLowerCase()}</small></button>
       {folder.name&&<div><button title={t.rename} onClick={()=>renameFolder(folder.name)}>E</button><button className="danger" title={t.deleteFolder} onClick={()=>setDeleteFolder(folder)}>X</button></div>}
      </div>)}
     </div>
    </aside>
    <section className="library-panel">
     <div className="toolbar"><h2>{folderFilter===undefined?t.library:folderLabel(folderFilter,t)} <small>{visibleBooks.length}</small></h2><div><button className="primary" onClick={()=>setCreating(true)}>{t.createGuide}</button><button onClick={()=>setImporting(true)}>{t.importRunbook}</button></div></div>
     <section className="tag-strip" aria-label={t.tags}>{allTags.map(tag=><button key={tag} className={tagFilter===tag?'tag-chip active':'tag-chip'} onClick={()=>setTagFilter(tagFilter===tag?'':tag)}>{tag}</button>)}</section>
     <section className="compact-cards">{visibleBooks.map(item=>{
      const isExpanded=expanded.has(item.id);
      return <article className={isExpanded?'workflow-card expanded':'workflow-card'} key={item.id} onClick={()=>setExpanded(ids=>{const next=new Set(ids);if(next.has(item.id))next.delete(item.id);else next.add(item.id);return next})}>
       <div className="workflow-main">
        <div><div className="category">{folderLabel(folderOf(item),t).toUpperCase()}</div><h3>{localize(item.title,lang)}</h3></div>
        <div className="workflow-actions" onClick={event=>event.stopPropagation()}>
         <button className="primary" title={t.runHelp} onClick={()=>{setSite(false);open(item,'run')}}>{t.run}</button>
         <button title={t.editHelp} onClick={()=>open(item,'edit')}>{t.edit}</button>
         <button className="danger" title={t.deleteGuide} onClick={()=>removeBook(item)}>{t.delete}</button>
         <details className="overflow-menu"><summary aria-label={t.menu}>...</summary><div>
          <button onClick={()=>duplicate(item)}>{t.duplicate}</button>
          <button onClick={()=>download(item)}>{t.exportJson}</button>
          <button onClick={()=>setMoving({bookId:item.id,folder:folderOf(item)})}>{t.moveFolder}</button>
          <button onClick={()=>setExpanded(ids=>new Set(ids).add(item.id))}>{t.metadata}</button>
         </div></details>
        </div>
       </div>
       {isExpanded&&<div className="workflow-detail">
        <p>{localize(item.description,lang)||t.collapsedHint}</p>
        <div className="tags horizontal-tags">{item.tags.map(tag=><button className="tag-chip" key={tag} onClick={event=>{event.stopPropagation();setTagFilter(tag)}}>{tag}</button>)}</div>
        <div className="detail-actions" onClick={event=>event.stopPropagation()}><button onClick={()=>{setSite(true);open(item,'run')}}>{t.siteLabel}</button><button onClick={()=>setMoving({bookId:item.id,folder:folderOf(item)})}>{t.move}</button><span>{item.nodes.length} {t.node}</span><span>{item.metadata?.updatedAt?.slice(0,10)}</span></div>
       </div>}
      </article>
     })}</section>
    </section>
   </section>

   <section className="recents" id="recents"><h2>{t.recent}</h2>{recents.length===0?<p>{t.recentEmpty}</p>:recents.slice(0,8).map(item=><button key={item.id} onClick={()=>{const recentBook=books.find(b=>b.id===item.bookId);if(recentBook)open(recentBook,'run',item.nodeId);else if(item.query)setSearch(item.query)}}><span>{item.label}</span><small>{new Date(item.at).toLocaleString()}</small></button>)}</section>
  </main>}

  {book&&mode==='run'&&<Runner key={`${book.id}-${targetNode??'start'}-${lang}-${site}`} book={book} onsite={site} setOnsite={setSite} startAt={targetNode} lang={lang} t={t} markRecent={addRecent}/>}
  {book&&mode==='edit'&&<Editor initial={book} onSave={update} onExit={()=>setMode('library')} lang={lang} t={t}/>}
  {importing&&<Importer books={books} close={()=>setImporting(false)} accept={acceptBook} lang={lang} t={t}/>}
  {creating&&<CreateRunbookModal close={()=>setCreating(false)} accept={createBook} lang={lang} t={t} folders={folders}/>}
  {quickCreate&&<QuickSolutionModal query={quickCreate} close={()=>setQuickCreate(undefined)} accept={saveQuick} lang={lang} t={t}/>}
  {deleteFolder&&<FolderDeleteModal intent={deleteFolder} close={()=>setDeleteFolder(undefined)} t={t} apply={deleteContents=>{setFolders(items=>items.filter(folder=>folder.name!==deleteFolder.name));setBooks(items=>deleteContents?items.filter(book=>folderOf(book)!==deleteFolder.name):items.map(book=>folderOf(book)===deleteFolder.name?{...book,folder:uncategorized}:book));if(folderFilter===deleteFolder.name)setFolderFilter(undefined);setDeleteFolder(undefined)}}/>}
  {moving&&<MoveFolderModal moving={moving} folders={folders} t={t} close={()=>setMoving(undefined)} apply={moveBook}/>}
  {mode==='library'&&<nav className="bottom-nav"><a href="#search">{t.search}</a><a href="#library">{t.library}</a><button onClick={()=>setCreating(true)}>{t.add}</button><a href="#recents">{t.recent}</a><button onClick={()=>setImporting(true)}>{t.importRunbook}</button></nav>}
 </div>
}

function searchResults(books:Runbook[],query:string,tagFilter:string,lang:Language):SearchResult[]{const filtered=books.filter(book=>!tagFilter||book.tags.some(tag=>normalize(tag)===normalize(tagFilter)));if(!query.trim())return [];const results:SearchResult[]=[];for(const book of filtered){const bookText=[...collectLocalizedText(book.title),...collectLocalizedText(book.description),book.category,book.folder??'',...book.tags].join(' ');const bookScore=scoreText(query,bookText);if(bookScore>0)results.push({book,score:bookScore,snippet:localize(book.description,lang)});for(const node of book.nodes){const text=nodeSearchText(book,node);const score=scoreText(query,text)+(node.type==='troubleshooting'?18:0);if(score>18)results.push({book,node,score,snippet:bestSnippet(query,text)})}}return results.sort((a,b)=>b.score-a.score).slice(0,8)}
function MediaView({node,lang}:{node:RunbookNode;lang:Language}){return <>{node.media?.map((media,index)=>media.type==='image'?<figure key={index}><a href={media.url} target="_blank"><img src={media.url} alt={localize(media.alt,lang)}/></a>{media.caption&&<figcaption>{localize(media.caption,lang)}</figcaption>}</figure>:<figure key={index}><video controls preload="metadata" src={media.url}/>{media.caption&&<figcaption>{localize(media.caption,lang)}</figcaption>}</figure>)}</>}

function Runner({book,onsite,setOnsite,startAt,lang,t,markRecent}:{book:Runbook;onsite:boolean;setOnsite:(value:boolean)=>void;startAt?:string;lang:Language;t:Record<string,string>;markRecent:(item:Omit<RecentItem,'id'|'at'>)=>void}){const saved=loadProgress()[book.id]??[];const initial=startAt&&getNode(book,startAt)?[startAt]:saved.length?saved:[book.startNode];const [history,setHistory]=useState<string[]>(initial);const [copied,setCopied]=useState(false);const id=history.at(-1)??book.startNode;const node=getNode(book,id);useEffect(()=>{const progress=loadProgress();progress[book.id]=history;saveProgress(progress);const current=getNode(book,history.at(-1)??book.startNode);if(current)markRecent({bookId:book.id,nodeId:current.id,type:'step',label:localize(current.title,lang)})},[book,history,lang,markRecent]);if(!node)return <main><p>{t.missingNode}: {id}</p></main>;const go=(next?:string)=>next&&setHistory(items=>[...items,next]);const copyCommand=()=>{if(!node.command)return;navigator.clipboard.writeText(node.command);setCopied(true);setTimeout(()=>setCopied(false),1400)};return <main className={onsite?'runner onsite':'runner'}><div className="runbar"><div><p className="eyebrow">{onsite?t.siteLabel:t.run} / {book.category}</p><h2>{localize(book.title,lang)}</h2></div><label className="toggle"><input type="checkbox" checked={onsite} onChange={event=>setOnsite(event.target.checked)}/> {t.onsite}<small>{t.onsiteHelp}</small></label></div>{!onsite&&<div className="crumbs">{history.map((nodeId,index)=><button key={`${nodeId}${index}`} onClick={()=>setHistory(items=>items.slice(0,index+1))}>{index+1}. {localize(getNode(book,nodeId)?.title??'',lang)}</button>)}</div>}<article className={`step ${node.type}`}><p className="step-type">{node.type.replace('-',' ').toUpperCase()}</p><h1>{localize(node.title,lang)}</h1>{node.body&&<p className="body">{localize(node.body,lang)}</p>}{!onsite&&node.symptoms?.length?<div className="meta-list"><b>{t.symptoms}</b>{node.symptoms.map((symptom,index)=><span key={index}>{localize(symptom,lang)}</span>)}</div>:null}<MediaView node={node} lang={lang}/>{node.command&&<div className="command">{node.destructive&&<strong>{t.warning}: {t.verifyBeforeRunning}.</strong>}<div><code>{node.command}</code><button onClick={copyCommand}>{copied?t.copied:t.copy}</button></div>{!onsite&&node.expectedResult&&<p><b>{t.expected}:</b> {localize(node.expectedResult,lang)}</p>}</div>}<div className="outcomes">{node.outcomes?.map(outcome=><button key={outcome.id} onClick={()=>go(outcome.nextNode)}>{localize(outcome.label,lang)}<span>-&gt;</span></button>)}{node.nextNode&&<button className="primary" onClick={()=>go(node.nextNode)}>{t.continue}<span>-&gt;</span></button>}{node.type==='solution'&&<button className="success" onClick={()=>markRecent({bookId:book.id,nodeId:node.id,type:'resolved',label:localize(node.title,lang)})}>OK {t.markSolved}</button>}</div></article><div className="runner-nav"><button disabled={history.length<2} onClick={()=>setHistory(items=>items.slice(0,-1))}>&lt;- {t.back}</button><button onClick={()=>setHistory([book.startNode])}>Reset</button></div></main>}

function Importer({close,accept,books,lang,t}:{close:()=>void;accept:(book:Runbook)=>void;books:Runbook[];lang:Language;t:Record<string,string>}){const [candidate,setCandidate]=useState<Runbook>();const [errors,setErrors]=useState<string[]>([]);const read=(file?:File)=>{if(!file)return;const reader=new FileReader();reader.onload=()=>{try{const data=migrateRunbook(JSON.parse(String(reader.result)) as Runbook);const result=validateRunbook(data);setErrors([...result.errors,...result.warnings.map(warning=>`${t.warnings}: ${warning}`)]);setCandidate(result.valid?data:undefined)}catch(error){setErrors([`/: Invalid JSON - ${error instanceof Error?error.message:'parse failed'}`]);setCandidate(undefined)}};reader.readAsText(file)};return <div className="modal" role="dialog" aria-modal="true"><section><button className="close" onClick={close}>x</button><p className="eyebrow">{t.importRunbook}</p><h2>{t.importTitle}</h2><label className="drop" onDragOver={event=>event.preventDefault()} onDrop={event=>{event.preventDefault();read(event.dataTransfer.files[0])}}>{t.drop}<br/><span>{t.choose}</span><input type="file" accept=".json,application/json" onChange={event=>read(event.target.files?.[0])}/></label>{errors.length>0&&<div className={candidate?'warnings':'errors'}><b>{candidate?t.reviewWarnings:t.validationFailed}</b>{errors.map((error,index)=><p key={index}>{error}</p>)}</div>}{candidate&&<div className="preview"><b>{t.preview}</b><h3>{localize(candidate.title,lang)}</h3><p>{localize(candidate.description,lang)}</p><p>{candidate.nodes.length} {t.node} / {candidate.category}</p>{books.some(book=>book.id===candidate.id)&&<p>{t.replaceNotice}</p>}<button className="primary" onClick={()=>accept(candidate)}>{t.importIntoLibrary}</button></div>}</section></div>}
function CreateRunbookModal({close,accept,lang,t,folders}:{close:()=>void;accept:(book:Runbook)=>void;lang:Language;t:Record<string,string>;folders:FolderItem[]}){const [title,setTitle]=useState('');const [folder,setFolder]=useState(folders[0]?.name??'General');const create=()=>{const name=title.trim();const folderName=folder.trim()||uncategorized;const book:Runbook={schemaVersion:2,id:slugify(name),title:localized(name,lang),description:localized('',lang),category:folderName||'General',folder:folderName,tags:[],metadata:{author:'Tech Runbook',version:'1.0.0',updatedAt:new Date().toISOString()},startNode:'start',nodes:[{id:'start',type:'action',title:localized('START',lang),body:localized('',lang),outcomes:[],ui:{x:0,y:0}}]};accept(book)};return <div className="modal" role="dialog" aria-modal="true"><section className="compact-modal"><button className="close" onClick={close}>x</button><p className="eyebrow">{t.createGuide}</p><h2>{t.newGuide}</h2><div className="form-grid"><label>{t.guideName}<input value={title} onChange={event=>setTitle(event.target.value)} autoFocus/></label><label>{t.folder}<input list="folder-options" value={folder} onChange={event=>setFolder(event.target.value)}/><datalist id="folder-options">{folders.map(item=><option value={item.name} key={item.id}/>)}</datalist></label></div><button className="primary wide" disabled={!title.trim()} onClick={create}>{t.create}</button></section></div>}

function QuickSolutionModal({query,close,accept,lang,t}:{query:string;close:()=>void;accept:(book:Runbook)=>void;lang:Language;t:Record<string,string>}){const [problem,setProblem]=useState(query);const [variants,setVariants]=useState(query);const [description,setDescription]=useState('');const [cause,setCause]=useState('');const [steps,setSteps]=useState('');const [command,setCommand]=useState('');const [expected,setExpected]=useState('');const [finalSolution,setFinalSolution]=useState('');const [tags,setTags]=useState('');const save=()=>{const id=slugify(problem);const stepLines=toLines(steps);const nodes:RunbookNode[]=[{id:'start',type:'troubleshooting',title:localized(problem,lang),body:localized(description,lang),symptoms:[localized(problem,lang)],errorMessages:toLines(variants),aliases:toLines(variants).map(item=>localized(item,lang)),keywords:[...splitList(tags),...normalize(problem).split(' ')],tags:splitList(tags),cause:localized(cause,lang),outcomes:stepLines.length?[{id:'seguir','label':localized(t.addNext,lang),'nextNode':'step-1'}]:command?[{id:'command','label':localized(t.addCommand,lang),'nextNode':'command'}]:[{id:'solution','label':localized(t.markAsSolution,lang),'nextNode':'solution'}]},...stepLines.map((line,index)=>({id:`step-${index+1}`,type:'action' as NodeType,title:localized(`${t.step} ${index+1}`,lang),body:localized(line,lang),nextNode:index<stepLines.length-1?`step-${index+2}`:command?'command':'solution'})),...(command?[{id:'command',type:'command' as NodeType,title:localized(t.optionalCommand,lang),command,expectedResult:localized(expected,lang),nextNode:'solution'}]:[]),{id:'solution',type:'solution',title:localized(finalSolution||problem,lang),body:localized(finalSolution||expected||description,lang),finalSolution:localized(finalSolution,lang)}];accept({schemaVersion:2,id,title:localized(problem,lang),description:localized(description||problem,lang),category:'Troubleshooting',folder:'Troubleshooting',tags:splitList(tags),metadata:{author:'Tech Runbook',version:'1.0.0',updatedAt:new Date().toISOString(),createdFrom:query},startNode:'start',nodes})};return <div className="modal" role="dialog" aria-modal="true"><section><button className="close" onClick={close}>x</button><p className="eyebrow">{t.noResults}</p><h2>{t.solutionEditor}</h2><div className="form-grid"><label>{t.errorProblem}<input value={problem} onChange={event=>setProblem(event.target.value)} autoFocus/></label><label>{t.tags}<input value={tags} onChange={event=>setTags(event.target.value)} placeholder="Vite, npm"/></label><label>{t.variants}<textarea rows={3} value={variants} onChange={event=>setVariants(event.target.value)} placeholder="vite is not recognized&#10;vite: command not found"/></label><label>{t.description}<textarea rows={3} value={description} onChange={event=>setDescription(event.target.value)}/></label><label>{t.possibleCause}<textarea rows={2} value={cause} onChange={event=>setCause(event.target.value)}/></label><label>{t.step} 1, 2...<textarea rows={5} value={steps} onChange={event=>setSteps(event.target.value)} placeholder={t.oneStepPerLine}/></label><label>{t.optionalCommand}<textarea rows={4} value={command} onChange={event=>setCommand(event.target.value)}/></label><label>{t.finalSolution}<textarea rows={3} value={finalSolution} onChange={event=>setFinalSolution(event.target.value)}/></label><label>{t.expectedResult}<input value={expected} onChange={event=>setExpected(event.target.value)}/></label></div><button className="primary wide" disabled={!problem.trim()} onClick={save}>{t.saveInLibrary}</button></section></div>}

function Editor({initial,onSave,onExit,lang,t}:{initial:Runbook;onSave:(book:Runbook)=>void;onExit:()=>void;lang:Language;t:Record<string,string>}){return <ReactFlowProvider><FlowEditor initial={initial} onSave={onSave} onExit={onExit} lang={lang} t={t}/></ReactFlowProvider>}
function FlowEditor({initial,onSave,onExit,lang,t}:{initial:Runbook;onSave:(book:Runbook)=>void;onExit:()=>void;lang:Language;t:Record<string,string>}){const draftKey=`tech-runbook.draft.${initial.id}`;const [book,setBook]=useState<Runbook>(()=>{try{return migrateRunbook(JSON.parse(localStorage.getItem(draftKey)??'null')||clone(initial))}catch{return clone(initial)}});const [past,setPast]=useState<Runbook[]>([]);const [future,setFuture]=useState<Runbook[]>([]);const [active,setActive]=useState(initial.startNode);const [openAddKey,setOpenAddKey]=useState<string>();const [showJson,setShowJson]=useState(false);const dirty=JSON.stringify(book)!==JSON.stringify(initial);const validation=validateRunbook(book);const activeNode=getNode(book,active)??getNode(book,book.startNode);useEffect(()=>{if(dirty)localStorage.setItem(draftKey,JSON.stringify(book))},[book,dirty,draftKey]);const mutate=(fn:(draft:Runbook)=>void)=>{setPast(items=>[...items.slice(-24),clone(book)]);setFuture([]);const next=clone(book);fn(next);setBook(next)};const setText=(value:LocalizedString|undefined,nextValue:string):LocalizedString=>typeof value==='string'?{es:lang==='es'?nextValue:value,en:lang==='en'?nextValue:value}:{...value,[lang]:nextValue};const undo=()=>{const item=past.at(-1);if(item){setFuture(items=>[clone(book),...items]);setBook(item);setPast(items=>items.slice(0,-1))}};const redo=()=>{const item=future[0];if(item){setPast(items=>[...items,clone(book)]);setBook(item);setFuture(items=>items.slice(1))}};const makeNode=(type:NodeType,title=nodeTypeLabel(type,t)):RunbookNode=>{const base:RunbookNode={id:'',type,title:localized(title,lang),body:localized('',lang),outcomes:[]};if(type==='question')base.outcomes=[{id:'si',label:localized(t.yes,lang)},{id:'no',label:localized(t.no,lang)}];if(type==='command')base.command='';if(type==='troubleshooting')base.errorMessages=[];return base};const uniqueNodeId=(title:string)=>{let id=slugify(title),i=2;while(book.nodes.some(item=>item.id===id))id=`${slugify(title)}-${i++}`;return id};const addLinkedNode=(sourceId:string,type:NodeType,outcomeId?:string)=>{const title=nodeTypeLabel(type,t);const id=uniqueNodeId(title);mutate(draft=>{const source=getNode(draft,sourceId);if(!source)return;const next=makeNode(type,title);next.id=id;const outcome=source.outcomes?.find(item=>item.id===outcomeId);const previousTarget=outcome?outcome.nextNode:source.nextNode;next.nextNode=previousTarget;draft.nodes.push(next);if(outcome)outcome.nextNode=id;else source.nextNode=id});setActive(id);setOpenAddKey(undefined)};const insertBetween=(sourceId:string,targetId:string,outcomeId?:string)=>{const title=t.step;const id=uniqueNodeId(title);mutate(draft=>{const source=getNode(draft,sourceId);if(!source)return;const next=makeNode('action',title);next.id=id;next.nextNode=targetId;draft.nodes.push(next);const outcome=source.outcomes?.find(item=>item.id===outcomeId);if(outcome)outcome.nextNode=id;else if(source.nextNode===targetId)source.nextNode=id});setActive(id)};const addOutcome=(sourceId:string)=>mutate(draft=>{const source=getNode(draft,sourceId);if(!source)return;source.outcomes=[...(source.outcomes??[]),{id:`outcome-${(source.outcomes?.length??0)+1}`,label:localized(t.addOutcome,lang)}]});const addBefore=()=>{if(!activeNode)return;const id=uniqueNodeId(t.step);mutate(draft=>{const next=makeNode('action',t.step);next.id=id;next.nextNode=activeNode.id;draft.nodes.forEach(item=>{if(item.nextNode===activeNode.id)item.nextNode=id;item.outcomes?.forEach(outcome=>{if(outcome.nextNode===activeNode.id)outcome.nextNode=id})});if(draft.startNode===activeNode.id)draft.startNode=id;draft.nodes.push(next)});setActive(id)};const addAfter=()=>activeNode&&addLinkedNode(activeNode.id,'action');const remove=()=>{if(!activeNode)return;if(activeNode.id===book.startNode&&book.nodes.length>1){alert('START cannot be deleted while other nodes exist.');return}if(confirm(`${t.deleteGuide}: "${localize(activeNode.title,lang)}"?`))mutate(draft=>{const fallback=activeNode.nextNode;draft.nodes.forEach(item=>{if(item.nextNode===activeNode.id)item.nextNode=fallback;item.outcomes?.forEach(outcome=>{if(outcome.nextNode===activeNode.id)outcome.nextNode=fallback})});draft.nodes=draft.nodes.filter(item=>item.id!==activeNode.id);draft.startNode=draft.startNode===activeNode.id?(draft.nodes[0]?.id??'start'):draft.startNode;setActive(draft.startNode)})};const duplicateNode=()=>{if(!activeNode)return;const id=uniqueNodeId(`${localize(activeNode.title,lang)} copy`);mutate(draft=>draft.nodes.push({...clone(activeNode),id,title:setText(activeNode.title,`${localize(activeNode.title,lang)} copy`),ui:{x:(activeNode.ui?.x??0)+36,y:(activeNode.ui?.y??0)+36}}));setActive(id)};const relayout=()=>mutate(draft=>{const layout=layoutRunbook(draft,isMobileLayout());draft.nodes.forEach(node=>{node.ui=layout[node.id]})});const onNodeDragStop:OnNodeDrag<FlowNode>=(_,flowNode)=>mutate(draft=>{const node=getNode(draft,flowNode.id);if(node)node.ui={x:Math.round(flowNode.position.x),y:Math.round(flowNode.position.y)}});const {nodes,edges}=toFlowElements(book,active,lang,t,openAddKey,setActive,setOpenAddKey,addLinkedNode,addOutcome,insertBetween);const nodeTypes=useMemo(()=>({runbook:FlowNodeCard}),[]);const edgeTypes=useMemo(()=>({insert:InsertEdgeButton}),[]);return <main className="editor visual-editor"><div className="editor-head"><div><p className="eyebrow">{t.editorTitle}</p><input className="title-input" value={localize(book.title,lang)} onChange={event=>mutate(draft=>{draft.title=setText(draft.title,event.target.value)})}/></div><div><button disabled={!past.length} onClick={undo}>Undo</button><button disabled={!future.length} onClick={redo}>Redo</button><button onClick={relayout}>{t.autoLayout}</button><button onClick={()=>setShowJson(value=>!value)}>JSON</button><button onClick={()=>download(book)}>{t.exportJson}</button><button className="primary" disabled={!validation.valid} onClick={()=>{onSave({...book,metadata:{...book.metadata,updatedAt:new Date().toISOString()}});localStorage.removeItem(draftKey);onExit()}}>{t.save} {dirty?'*':''}</button></div></div><div className="visual-shell"><section className="flow-surface" aria-label={t.tree}><ReactFlow nodes={nodes} edges={edges} nodeTypes={nodeTypes} edgeTypes={edgeTypes} onNodeDragStop={onNodeDragStop} fitView minZoom={0.22} maxZoom={1.6} nodesDraggable nodesConnectable={false} proOptions={{hideAttribution:true}}><Background gap={22}/><MiniMap pannable zoomable className="flow-minimap"/><Controls showInteractive={false}/></ReactFlow><p className="flow-note">{t.visualOnly}</p></section>{activeNode&&<section className="inspector node-sheet"><div className="inspector-head"><div><p className="eyebrow">{activeNode.id===book.startNode?'START':activeNode.type}</p><h2>{localize(activeNode.title,lang)||t.node}</h2></div><div><button onClick={addBefore}>{t.addBefore}</button><button onClick={addAfter}>{t.addAfter}</button><button onClick={duplicateNode}>{t.duplicate}</button><button className="danger" onClick={remove}>{t.delete}</button></div></div><div className="quick-builder">{nodeTypesList.map(type=><button key={type} onClick={()=>addLinkedNode(activeNode.id,type)}>{nodeTypeLabel(type,t)}</button>)}<button onClick={()=>addOutcome(activeNode.id)}>{t.addOutcome}</button></div><div className="form-grid"><Field label={t.nodeId} value={activeNode.id} change={value=>mutate(draft=>{const current=getNode(draft,activeNode.id)!;const nextId=slugify(value);if(!nextId||draft.nodes.some(item=>item.id===nextId&&item.id!==activeNode.id))return;current.id=nextId;draft.nodes.forEach(item=>{if(item.nextNode===activeNode.id)item.nextNode=nextId;item.outcomes?.forEach(outcome=>{if(outcome.nextNode===activeNode.id)outcome.nextNode=nextId})});if(draft.startNode===activeNode.id)draft.startNode=nextId;setActive(nextId)})}/><label>{t.type}<select value={activeNode.type} onChange={event=>mutate(draft=>{getNode(draft,activeNode.id)!.type=event.target.value as NodeType})}>{nodeTypesList.map(type=><option key={type} value={type}>{nodeTypeLabel(type,t)}</option>)}</select></label><Field label={t.title} value={localize(activeNode.title,lang)} change={value=>mutate(draft=>{const current=getNode(draft,activeNode.id)!;current.title=setText(current.title,value)})}/><label>{t.body}<textarea rows={3} value={localize(activeNode.body,lang)} onChange={event=>mutate(draft=>{const current=getNode(draft,activeNode.id)!;current.body=setText(current.body,event.target.value)})}/></label>{(activeNode.type==='command'||activeNode.command!=null)&&<><label>{t.command}<textarea rows={3} value={activeNode.command??''} onChange={event=>mutate(draft=>{getNode(draft,activeNode.id)!.command=event.target.value})}/></label><Field label={t.expectedResult} value={localize(activeNode.expectedResult,lang)} change={value=>mutate(draft=>{const current=getNode(draft,activeNode.id)!;current.expectedResult=setText(current.expectedResult,value)})}/><label className="check"><input type="checkbox" checked={activeNode.destructive??false} onChange={event=>mutate(draft=>{getNode(draft,activeNode.id)!.destructive=event.target.checked})}/> {t.destructive}</label></>}</div>{activeNode.type==='troubleshooting'&&<TroubleshootingFields node={activeNode} lang={lang} t={t} mutate={mutate} active={activeNode.id} setText={setText}/>}<h3>{t.outcomes}</h3>{activeNode.outcomes?.map((outcome,index)=><OutcomeRow key={outcome.id+index} outcome={outcome} nodes={book.nodes} lang={lang} t={t} change={next=>mutate(draft=>{getNode(draft,activeNode.id)!.outcomes![index]=next})} remove={()=>mutate(draft=>{getNode(draft,activeNode.id)!.outcomes!.splice(index,1)})}/>) }<button onClick={()=>addOutcome(activeNode.id)}>{t.addOutcome}</button><h3>{t.defaultNext}</h3><select value={activeNode.nextNode??''} onChange={event=>mutate(draft=>{getNode(draft,activeNode.id)!.nextNode=event.target.value||undefined})}><option value="">{t.none}</option>{book.nodes.filter(item=>item.id!==activeNode.id).map(item=><option value={item.id} key={item.id}>{localize(item.title,lang)}</option>)}</select><h3>{t.validate}</h3><div className={validation.valid?'valid':'errors'}><b>{validation.valid?'OK '+t.valid:t.issues}</b>{[...validation.errors,...validation.warnings].map((error,index)=><p key={index}>{error}</p>)}</div></section>}</div>{showJson&&<pre className="json-preview">{JSON.stringify(book,null,2)}</pre>}</main>}

function toFlowElements(book:Runbook,active:string,lang:Language,t:Record<string,string>,openAddKey:string|undefined,onSelect:(id:string)=>void,onToggleAdd:(key?:string)=>void,onAdd:(sourceId:string,type:NodeType,outcomeId?:string)=>void,onAddOutcome:(sourceId:string)=>void,onInsert:(sourceId:string,targetId:string,outcomeId?:string)=>void){const layout=layoutRunbook(book,isMobileLayout());const links=flowLinks(book);const nodes:FlowNode[]=book.nodes.map(node=>({id:node.id,type:'runbook',position:{x:node.ui?.x??layout[node.id]?.x??0,y:node.ui?.y??layout[node.id]?.y??0},data:{node,isStart:node.id===book.startNode,isActive:node.id===active,label:localize(node.title,lang),body:localize(node.body,lang),t,lang,openAddKey,onSelect,onToggleAdd,onAdd,onAddOutcome}}));const edges:InsertEdge[]=links.map(link=>({id:`${link.source}-${link.outcomeId??'next'}-${link.target}`,source:link.source,target:link.target,type:'insert',label:link.label,data:{label:link.label,sourceId:link.source,targetId:link.target,outcomeId:link.outcomeId,onInsert},markerEnd:{type:MarkerType.ArrowClosed},style:{strokeWidth:2}}));return {nodes,edges}}
function flowLinks(book:Runbook){return book.nodes.flatMap(node=>{const next=node.nextNode?[{source:node.id,target:node.nextNode,label:'',outcomeId:undefined as string|undefined}]:[];const outcomes=(node.outcomes??[]).filter(outcome=>outcome.nextNode).map(outcome=>({source:node.id,target:outcome.nextNode!,label:localize(outcome.label,'es')||outcome.id,outcomeId:outcome.id}));return [...next,...outcomes]})}
function layoutRunbook(book:Runbook,vertical:boolean){const links=flowLinks(book);const children=new Map<string,string[]>();links.forEach(link=>children.set(link.source,[...(children.get(link.source)??[]),link.target]));const level=new Map<string,number>();const order:string[]=[];const visit=(id:string,depth:number,path:Set<string>)=>{if(path.has(id))return;if((level.get(id)??-1)<depth)level.set(id,depth);if(!order.includes(id))order.push(id);const nextPath=new Set(path).add(id);(children.get(id)??[]).forEach(child=>visit(child,depth+1,nextPath))};visit(book.startNode,0,new Set());book.nodes.forEach(node=>{if(!level.has(node.id)){level.set(node.id,Math.max(1,level.size));order.push(node.id)}});const groups=new Map<number,string[]>();order.forEach(id=>{const depth=level.get(id)??0;groups.set(depth,[...(groups.get(depth)??[]),id])});const positions:Record<string,{x:number;y:number}>={};groups.forEach((ids,depth)=>{ids.forEach((id,index)=>{const spread=(index-(ids.length-1)/2)*190;positions[id]=vertical?{x:spread,y:depth*250}:{x:depth*330,y:spread}})});return positions}
function isMobileLayout(){return typeof matchMedia==='function'&&matchMedia('(max-width: 760px)').matches}
function FlowNodeCard({data}:NodeProps<FlowNode>){const node=data.node;const nodeKey=`node:${node.id}`;return <div className={data.isActive?'flow-card active':'flow-card'} onClick={()=>data.onSelect(node.id)}><Handle type="target" position={Position.Left}/><Handle type="source" position={Position.Right}/><div className="flow-card-head"><span>{data.isStart?'START':node.type}</span><button onClick={event=>{event.stopPropagation();data.onSelect(node.id)}}>{data.t.edit}</button></div><h3>{data.label||data.t.node}</h3>{data.body&&<p>{data.body}</p>}{node.command&&<code>{node.command}</code>}<div className="node-outcome-row">{(node.outcomes??[]).map(outcome=>{const key=`outcome:${node.id}:${outcome.id}`;return <div key={outcome.id} className="outcome-branch"><span>{localize(outcome.label,data.lang)}</span><button title={data.t.addOutcome} onClick={event=>{event.stopPropagation();data.onToggleAdd(data.openAddKey===key?undefined:key)}}>+</button>{data.openAddKey===key&&<NodeAddMenu sourceId={node.id} outcomeId={outcome.id} add={data.onAdd} t={data.t}/>}</div>})}</div><div className="node-plus"><button onClick={event=>{event.stopPropagation();data.onToggleAdd(data.openAddKey===nodeKey?undefined:nodeKey)}}>+</button><button onClick={event=>{event.stopPropagation();data.onAddOutcome(node.id)}}>{data.t.addOutcome}</button>{data.openAddKey===nodeKey&&<NodeAddMenu sourceId={node.id} add={data.onAdd} t={data.t}/>}</div></div>}
function NodeAddMenu({sourceId,outcomeId,add,t}:{sourceId:string;outcomeId?:string;add:(sourceId:string,type:NodeType,outcomeId?:string)=>void;t:Record<string,string>}){return <div className="node-add-menu">{nodeTypesList.map(type=><button key={type} onClick={event=>{event.stopPropagation();add(sourceId,type,outcomeId)}}>{nodeTypeLabel(type,t)}</button>)}</div>}
function InsertEdgeButton(props:EdgeProps<InsertEdge>){const [edgePath,labelX,labelY]=getBezierPath(props);return <><BaseEdge path={edgePath} markerEnd={props.markerEnd} style={props.style}/><EdgeLabelRenderer><button className="edge-add" style={{transform:`translate(-50%, -50%) translate(${labelX}px, ${labelY}px)`}} onClick={event=>{event.stopPropagation();props.data?.onInsert(props.data.sourceId,props.data.targetId,props.data.outcomeId)}}>+ {props.data?.label||'Insert'}</button></EdgeLabelRenderer></>}
function Field({label,value,change}:{label:string;value:string;change:(value:string)=>void}){return <label>{label}<input value={value} onChange={event=>change(event.target.value)}/></label>}
function TroubleshootingFields({node,lang,t,mutate,active,setText}:{node:RunbookNode;lang:Language;t:Record<string,string>;mutate:(fn:(draft:Runbook)=>void)=>void;active:string;setText:(value:LocalizedString|undefined,nextValue:string)=>LocalizedString}){const listValue=(field:DraftNodeField)=>(node[field]??[]).map(item=>localize(item,lang)).join('\n');const textListChange=(field:DraftNodeField,value:string)=>mutate(draft=>{getNode(draft,active)![field]=toLines(value).map(item=>localized(item,lang))});return <div className="troubleshooting-fields form-grid"><label>{t.symptoms}<textarea rows={3} value={listValue('symptoms')} onChange={event=>textListChange('symptoms',event.target.value)}/></label><label>{t.errorMessages}<textarea rows={3} value={(node.errorMessages??[]).join('\n')} onChange={event=>mutate(draft=>{getNode(draft,active)!.errorMessages=toLines(event.target.value)})}/></label><label>{t.aliases}<textarea rows={3} value={listValue('aliases')} onChange={event=>textListChange('aliases',event.target.value)}/></label><label>{t.keywords}<input value={(node.keywords??[]).join(', ')} onChange={event=>mutate(draft=>{getNode(draft,active)!.keywords=splitList(event.target.value)})}/></label><label>{t.tags}<input value={(node.tags??[]).join(', ')} onChange={event=>mutate(draft=>{getNode(draft,active)!.tags=splitList(event.target.value)})}/></label><label>{t.possibleCause}<textarea rows={2} value={localize(node.cause,lang)} onChange={event=>mutate(draft=>{getNode(draft,active)!.cause=setText(getNode(draft,active)!.cause,event.target.value)})}/></label></div>}
function OutcomeRow({outcome,nodes,lang,t,change,remove}:{outcome:Outcome;nodes:RunbookNode[];lang:Language;t:Record<string,string>;change:(outcome:Outcome)=>void;remove:()=>void}){const setOutcomeText=(value:LocalizedString|undefined,nextValue:string):LocalizedString=>typeof value==='string'?{es:lang==='es'?nextValue:value,en:lang==='en'?nextValue:value}:{...value,[lang]:nextValue};return <div className="outcome-edit"><input aria-label="Outcome label" value={localize(outcome.label,lang)} onChange={event=>change({...outcome,label:setOutcomeText(outcome.label,event.target.value)})}/><select aria-label="Next node" value={outcome.nextNode??''} onChange={event=>change({...outcome,nextNode:event.target.value||undefined})}><option value="">{t.end}</option>{nodes.map(node=><option key={node.id} value={node.id}>{localize(node.title,lang)}</option>)}</select><button className="danger" onClick={remove}>x</button></div>}
function FolderDeleteModal({intent,close,apply,t}:{intent:DeleteFolderIntent;close:()=>void;apply:(deleteContents:boolean)=>void;t:Record<string,string>}){return <div className="modal" role="dialog" aria-modal="true"><section className="compact-modal"><button className="close" onClick={close}>x</button><p className="eyebrow">{t.deleteFolder}</p><h2>{t.deleteFolderTitle}: {intent.name}</h2><p>{intent.count} {t.procedures.toLowerCase()}</p><div className="modal-actions"><button onClick={close}>{t.cancel}</button><button onClick={()=>apply(false)}>{t.moveToNoFolder}</button><button className="danger" onClick={()=>apply(true)}>{t.deleteFolderAndContent}</button></div></section></div>}
function MoveFolderModal({moving,folders,close,apply,t}:{moving:MoveMenu;folders:FolderItem[];close:()=>void;apply:(bookId:string,folder:string)=>void;t:Record<string,string>}){const [folder,setFolder]=useState(moving.folder);return <div className="modal" role="dialog" aria-modal="true"><section className="compact-modal"><button className="close" onClick={close}>x</button><p className="eyebrow">{t.moveFolder}</p><h2>{t.moveFolder}</h2><label>{t.folder}<select value={folder} onChange={event=>setFolder(event.target.value)}><option value={uncategorized}>{t.noFolder}</option>{folders.map(item=><option key={item.id} value={item.name}>{item.name}</option>)}</select></label><button className="primary wide" onClick={()=>apply(moving.bookId,folder)}>{t.move}</button></section></div>}
